  </div>
</header>`;

  const scale = [1, 2, 3, 4, 5]
    .map(
      (value) =>
        `<span class="site-scale${value === 4 ? " site-scale-chosen" : ""} flex h-11 flex-1 items-center justify-center rounded-control border text-[17px] font-semibold tabular-nums">${value}</span>`,
    )
